// === Tab: sketch.js ===


// Reaction-Diffusion © 2024-05-15 by Zaron Chen is licensed under the MIT License. See LICENSE for more details. // // Interaction // - Mouse Drag: Interact with the canvas by dragging the mouse // - Space Bar: Press the space bar to toggle between a black and white cursor // // References // The implementation is based on these videos: // - noones img - Reaction-diffusion in 20 seconds (Touchdesginer tutorial): https://www.youtube.com/watch?v=CzmRMKQBMSw // - ArtOfSoulburn - Reaction Diffusion In Photoshop: https://www.youtube.com/watch?v=I6Vh_NOy70M // - SkyBase - Tutorial: Reaction-Diffusion in Photoshop: https://vimeo.com/61154654
import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.2.0/src/p5.flex.mjs"
/* [Inlined Multi-Tab] shader.js */
p5.disableFriendlyErrors = true
mountFlex(p5)
new p5((p) => {
const [WIDTH, HEIGHT] = [600, 600]
const PIXEL_DENSITY = 1
const TEXEL_SIZE = [1 / (WIDTH * PIXEL_DENSITY), 1 / (HEIGHT * PIXEL_DENSITY)]
const RENDERER = p.WEBGL
const MIN_SIDE = p.min(WIDTH, HEIGHT)
let cnv, gfx, img
let BlurPass, UnsharpPass
let CURSOR_COLOR = 255

// Variables pour l'let startTime
let blackPixels = []
let exported = false

p.preload = () => (img = p.loadImage("https://openprocessing.org/sketch/2861725/files/NoiseMono_2.png"))

p.setup = () => {
	cnv = p.createCanvas(WIDTH, HEIGHT, RENDERER)
	p.flex({ container: { padding: "20px" }, canvas: { fit: p.SCALE_DOWN } })
	p.pixelDensity(PIXEL_DENSITY)

	gfx = p.createGraphics(WIDTH, HEIGHT, p.WEBGL)

	BlurPass = p.createShader(VERT, BLUR)
	UnsharpPass = p.createShader(VERT, UNSHARP)

	RENDERER === p.WEBGL && p.rectMode(p.CENTER)
	RENDERER === p.WEBGL && p.imageMode(p.CENTER)

	p.background(0)
	p.noStroke()
	gfx.noStroke()

	p.image(img, 0, 0, WIDTH, HEIGHT)

	for (let _ = 0; _ < 3; _++) p.draw()

	// Démarrer le timer
	startTime = p.millis()
}

p.draw = () => {
	Cursor()
	Border()
	ReactionDiffusion()

	// Vérifier si 10 secondes sont écoulées
	if (!exported && p.millis() - startTime > 1000) {
		extractBlackPixels()
		exported = true
	}
}

p.keyPressed = () => p.key === " " && (CURSOR_COLOR = CURSOR_COLOR ? 0 : 255)

const Cursor = () => {
	p.push()
	RENDERER === p.WEBGL && p.translate(-WIDTH / 2, -HEIGHT / 2)
	p.fill(CURSOR_COLOR)
	p.mouseIsPressed && p.circle(p.mouseX, p.mouseY, MIN_SIDE / 6)
	p.pop()
}

const Border = () => {
	p.push()
	p.noFill()
	p.stroke(255)
	p.strokeWeight(MIN_SIDE / 6)
	p.rect(0, 0, WIDTH, HEIGHT)
	p.pop()
}

const ReactionDiffusion = () => {
	gfx.shader(BlurPass)
	BlurPass.setUniform("texelSize", TEXEL_SIZE)
	BlurPass.setUniform("tex0", cnv)
	BlurPass.setUniform("direction", [1, 0])
	gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

	gfx.shader(BlurPass)
	BlurPass.setUniform("texelSize", TEXEL_SIZE)
	BlurPass.setUniform("tex0", gfx)
	BlurPass.setUniform("direction", [0, 1])
	gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

	gfx.shader(UnsharpPass)
	UnsharpPass.setUniform("texelSize", TEXEL_SIZE)
	UnsharpPass.setUniform("tex0", gfx)
	gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

	p.image(gfx, 0, 0)
}

const extractBlackPixels = () => {
	// Récupérer les pixels du canvas
	p.loadPixels()
	p.background(255)

	// Parcourir tous les pixels
	for (let y = 0; y < HEIGHT; y++) {
		for (let x = 0; x < WIDTH; x++) {
			let index = (y * WIDTH + x) * 4
			let r = p.pixels[index]
			let g = p.pixels[index + 1]
			let b = p.pixels[index + 2]

			// Si le pixel est noir (ou très sombre)
			let brightness = (r + g + b) / 3
			if (brightness < 50) { // Seuil ajustable
				// Convertir en coordonnées WEBGL (centrées)
				let xWebGL = x - WIDTH / 2
				let yWebGL = y - HEIGHT / 2

				blackPixels.push({ x: xWebGL, y: yWebGL })
				p.fill(0)
				p.rect(xWebGL, yWebGL, 1)
				p.noLoop()
			}
		}
	}

	console.log(`${blackPixels.length} pixels noirs trouvés`)
	// console.log('Premiers pixels:', blackPixels.slice(0, 10))
}
})


// === Tab: shader.js ===

import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.2.0/src/Shox.js"

const BLUR = `#version 300 es
	precision highp float;

	uniform sampler2D tex0;
	uniform vec2 texelSize;
	uniform vec2 direction;

	${Shox.blur(3)}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() { fragColor = blur(vTexCoord, tex0, texelSize, direction); }
`

const UNSHARP = `#version 300 es
	precision mediump float;

	uniform sampler2D tex0;
	uniform vec2 texelSize;

	${Shox.unsharp}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() { fragColor = unsharp(vTexCoord, tex0, texelSize*7., 64.); }
`

const VERT = `#version 300 es

	in vec4 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		gl_Position = aPosition;
	}
`

